        <h1 id="support-title">Contact our team</h1>
        <p class="intro">Tell us how to reach you and our support team will follow up as soon as possible.</p>

        <form id="contact-form" novalidate>
          <p class="required-note"><span class="required" aria-hidden="true">*</span> indicates a required field.</p>

          <div class="form-field">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input id="full-name" name="fullName" type="text" autocomplete="name" required>
            <p class="error" id="full-name-error" hidden>Error: Enter your full name.</p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
            <input id="email" name="email" type="email" autocomplete="email" required>
            <p class="error" id="email-error" hidden>Error: Enter a valid email address, like name@example.com.</p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number <span>(optional)</span></label>
            <input id="phone" name="phone" type="tel" autocomplete="tel" aria-describedby="phone-help">
            <p class="helper" id="phone-help">Use 10 digits, optionally with spaces, dashes, parentheses, or a leading +.</p>
            <p class="error" id="phone-error" hidden>Error: Enter a phone number using digits, spaces, dashes, parentheses, or a leading +.</p>
          </div>

          <button type="submit">Send request</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#contact-form");
      const status = document.querySelector("#form-status");

      const fields = {
        fullName: {
          input: document.querySelector("#full-name"),
          error: document.querySelector("#full-name-error"),
          isValid: (value) => value.trim().length > 0
        },
        email: {
          input: document.querySelector("#email"),
          error: document.querySelector("#email-error"),
          isValid: (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
        },
        phone: {
          input: document.querySelector("#phone"),
          error: document.querySelector("#phone-error"),
          helpId: "phone-help",
          isValid: (value) => {
            const trimmed = value.trim();
            return trimmed === "" || /^\+?[0-9\s().-]{7,20}$/.test(trimmed);
          }
        }
      };

      function setFieldError(field, hasError) {
        const describedBy = field.helpId
          ? hasError ? `${field.helpId} ${field.error.id}` : field.helpId
          : hasError ? field.error.id : "";

        field.error.hidden = !hasError;

        if (hasError) {
          field.input.setAttribute("aria-invalid", "true");
        } else {
          field.input.removeAttribute("aria-invalid");
        }

        if (describedBy) {
          field.input.setAttribute("aria-describedby", describedBy);
        } else {
          field.input.removeAttribute("aria-describedby");
        }
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        let invalidField = null;

        Object.values(fields).forEach((field) => {
          const hasError = !field.isValid(field.input.value);
          setFieldError(field, hasError);

          if (hasError && invalidField === null) {
            invalidField = field;
          }
        });

        if (invalidField) {
          invalidField.input.focus();
          return;
        }

        status.textContent = "Thanks. Your support request is ready to send.";
        form.reset();
        Object.values(fields).forEach((field) => setFieldError(field, false));
      });

      Object.values(fields).forEach((field) => {
        field.input.addEventListener("input", () => {
          if (field.input.getAttribute("aria-invalid") === "true") {
